import json
d=json.load(open('layout.json'))
out=[]
def walk(o):
    if isinstance(o,dict):
        if o.get('type')=='text': out.append(o.get('text',''))
        elif o.get('type')=='heading': out.append('\n\n## '+o.get('text','')+'\n')
        elif o.get('type')=='paragraph':
            out.append('\n')
            for c in o.get('inlineContent',[]): walk(c)
        elif o.get('type')=='codeVoice': out.append('\`'+o.get('code','')+'\`')
        else:
            for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
walk(d)
txt=''.join(out)
open('layout.txt','w').write(txt)
print(len(txt))
